// Prepare a structured research document before the interview
record CompanyResearch(
    String name,
    List<String> products,
    List<String> techStack,
    String recentNews,
    String culture
) {}

var research = new CompanyResearch(
    "Acme Corp",
    List.of("Payment Gateway", "Mobile Banking App"),
    List.of("Java 17", "Spring Boot", "PostgreSQL", "Kafka"), // From job description
    "Launched AI-powered fraud detection in Q4 2024",
    "Engineering blog emphasizes code quality and automated testing"
);

// Connect research to your interests
var myAlignment = "Your fraud detection system interests me because " +
    "my capstone project involved anomaly detection in transaction data. " +
    "I'd love to work with real-time Kafka streams at scale.";

// Bad example: generic statement
var genericAnswer = "I want to work here because it's a great company"; // Signals no research

// Create a research checklist before every interview
record CompanyProfile(
    String name,
    int foundedYear,
    String headquarters,
    int employeeCount,
    List<String> products,
    List<String> techStack,
    List<String> recentNews,
    String cultureNote
) {}

var profile = new CompanyProfile(
    "PayTech Solutions",
    2018,
    "Bangalore, India",
    1200,
    List.of("Merchant Payment API", "QR Code Platform", "Analytics Dashboard"),
    List.of("Java 17", "Spring Boot", "PostgreSQL", "Redis", "Kubernetes"),
    List.of(
        "Series B funding $50M raised Oct 2024",
        "Processed 100M transactions milestone",
        "Launched fraud detection ML model"
    ),
    "Engineering blog emphasizes test-driven development and continuous deployment"
);

// Connect research to your answer
var answer = String.format(
    "I know you're a %d-year-old fintech company with %d employees. " +
    "Your merchant payment API handles high transaction volumes, " +
    "and I saw you recently hit 100 million transactions processed. " +
    "I'm excited about your tech stack — Java 17 with Spring Boot and Kubernetes.",
    2024 - profile.foundedYear(), profile.employeeCount()
);

// Prepare questions in categories before the interview
record InterviewQuestion(
    String category,
    String question,
    String intent
) {}

var preparedQuestions = List.of(
    new InterviewQuestion(
        "Team Structure",
        "Can you describe the team I'd be joining? How many developers, and what's the mix of experience levels?",
        "Shows you care about collaboration and learning environment"
    ),
    new InterviewQuestion(
        "Tech Challenges",
        "What are the biggest technical challenges the team is facing right now with the Java backend?",
        "Shows you want to contribute and are thinking about real problems"
    ),
    new InterviewQuestion(
        "Growth Path",
        "How do you support Java developers in growing their skills? Are there mentorship programs or tech talks?",
        "Shows you're thinking about long-term growth, not just the first paycheck"
    ),
    new InterviewQuestion(
        "Personal Experience",
        "What do you enjoy most about working here, and what's been challenging?",
        "Shows you value honest perspective and want to understand culture"
    )
);

// Avoid these bad questions
var badQuestions = List.of(
    "What does your company do?", // Should already know this
    "How much vacation do I get?", // Premature, save for HR round
    "When will I get promoted?" // Overconfident before you've even started
);

// Structure your answer like this mental model
record InterviewStatus(
    boolean exploringOpportunities,
    List<String> reasonsForThisRole,
    String decisionCriteria
) {}

var myStatus = new InterviewStatus(
    true, // Honest about exploring options
    List.of(
        "Your team works on real-time payment processing with Kafka and Spring Boot",
        "The mentorship program pairs junior developers with senior engineers",
        "The engineering blog shows strong focus on code quality and testing"
    ),
    "I'm looking for a role where I can learn distributed systems and work with a team that values code quality"
);

// Good answer structure
var answer = String.format(
    "Yes, I'm talking with a few other companies, but I'm being selective. " +
    "What stands out about this role is %s. " +
    "That aligns with what I'm looking for: %s. " +
    "I'm not just optimizing for compensation — I want to join a team where I'll grow.",
    String.join(" and ", myStatus.reasonsForThisRole().subList(0, 2)),
    myStatus.decisionCriteria()
);

// Bad answer: overly transactional
var badAnswer = "I have three other offers. I'm just comparing which pays the most."; // Signals mercenary mindset

// Map what you've researched to your working style
record EngineeringCulture(
    String source,
    String practice,
    String yourAlignment
) {}

var researchFindings = List.of(
    new EngineeringCulture(
        "Engineering blog post on code reviews",
        "Every pull request requires two approvals before merge",
        "I value code reviews because they help me learn best practices early"
    ),
    new EngineeringCulture(
        "Job description",
        "Test-driven development with 80% code coverage requirement",
        "I've practiced TDD in my college projects and it helps me think through edge cases"
    ),
    new EngineeringCulture(
        "Glassdoor reviews",
        "Strong mentorship program pairing juniors with seniors",
        "I learn best when I can ask questions and get feedback from experienced developers"
    ),
    new EngineeringCulture(
        "GitHub repo activity",
        "Multiple commits daily with clear commit messages",
        "I prefer incremental development with frequent commits over large infrequent merges"
    )
);

// Bad example: no evidence
var genericAnswer = "I know you value collaboration and innovation."; // Every company claims this

// Good example: specific evidence
var specificAnswer = researchFindings.get(0).yourAlignment() + 
    " because " + researchFindings.get(0).practice();

// Think through legitimate reasons versus trivial ones
record DealBreaker(
    String reason,
    boolean legitimate,
    String explanation
) {}

var reasonsToLeave = List.of(
    new DealBreaker(
        "No learning opportunities",
        true,
        "If I'm stuck on maintenance work for two years with no exposure to new technologies or challenges"
    ),
    new DealBreaker(
        "Poor mentorship",
        true,
        "If there's no senior developer to learn from and no code review process"
    ),
    new DealBreaker(
        "Job mismatch",
        true,
        "If I'm hired for backend development but spend all my time on manual testing instead"
    ),
    new DealBreaker(
        "Ethical concerns",
        true,
        "If the company asks me to compromise on data privacy or security standards"
    ),
    new DealBreaker(
        "Slightly higher pay elsewhere",
        false,
        "This signals I'm mercenary and will leave for any small increase"
    ),
    new DealBreaker(
        "Not promoted within six months",
        false,
        "Unrealistic expectation as a fresher — promotions take time and demonstrated impact"
    )
);

// Good answer structure
var answer = "I'm committed to giving this role a genuine chance, but if " +
    reasonsToLeave.get(0).explanation() + ", I'd need to reconsider. " +
    "Growth is important to me, and I want to keep learning.";

